
/*! Hub Bootstrap Lite JS V104.31 - alert/dropdown/collapse básico para operação offline. */
(function(){'use strict';document.addEventListener('click',function(e){var close=e.target.closest('[data-bs-dismiss="alert"],.btn-close');if(close){var a=close.closest('.alert');if(a){a.remove();return;}}var toggle=e.target.closest('[data-bs-toggle="collapse"]');if(toggle){e.preventDefault();var sel=toggle.getAttribute('data-bs-target')||toggle.getAttribute('href');var el=sel?document.querySelector(sel):null;if(el){el.classList.toggle('show');}}var dd=e.target.closest('[data-bs-toggle="dropdown"]');if(dd){e.preventDefault();var menu=dd.parentElement?dd.parentElement.querySelector('.dropdown-menu'):null;if(menu)menu.classList.toggle('show');}});window.bootstrap=window.bootstrap||{Tooltip:function(){},Popover:function(){},Dropdown:function(){},Collapse:function(){}};})();
